// Timer: counts down for a fixed number of clock cycles, then goes high.
// One-shot terminal count: goes high for one clock cycle, then stays high
// until the counter is reloaded.
module TopModule(input clk, input load, input [9:0] data, output tc);
  reg [9:0] count;
  reg tc2;
  always @(posedge clk) begin
    if (load) count <= data;
    else count <= count - 1'b1;
    tc2 <= (count == 10'd0);
  end
  assign tc = tc2;
endmodule

