// Terminal count timer with a down-counter.
module TopModule (
  input  clk,
  input  load,
  input  [9:0] data,
  output tc
);
  reg [9:0] count;
  wire count_0;
  reg count_1;
  always @(posedge clk) begin
    if (load) count <= data;
    else count <= count - 1;
    count_0 <= (count == 0);
    count_1 <= (count == 1);
  end
  assign tc = count_0;
  // Trigger the FF to go to 0 independently of the count register, to
  // ensure that the tc signal is high exactly at the end of the timer.
  // This allows the timer to be reloaded right after it times out, with
  // zero extra latency.
  FD #(.INIT(1)) f0 (.C(clk), .D(count_0), .Q(tc));
endmodule

